"""Prompt rendering against the synthetic match itg-syn-0001 (generated by etl/seeder; not real data)."""
import json
from pathlib import Path

from narrative_engine.core.models import MatchClock
from narrative_engine.context.render import MatchInfo, describe, render_events, render_ledger, render_match, render_stats

FIXTURES = Path(__file__).parent / "fixtures"
with open(FIXTURES / "itg-syn-0001.jsonl") as f:
    MESSAGES = [json.loads(line) for line in f]
INFO = MatchInfo.from_ma1(MESSAGES[0])
EVENTS = MESSAGES[1:]


def minute_events(period, minute):
    return [e for e in EVENTS if (e["periodId"], e["timeMin"]) == (period, minute)]


def test_match_info_reads_teams_and_lineups():
    assert (INFO.home.name, INFO.home.code, INFO.away.name) == ("Riverside FC", "RIV", "Harbour Athletic")
    assert INFO.player("p-riv-09") == "Mensah" and INFO.synthetic
    assert "Synthetic" in render_match(INFO)


def test_goal_minute_names_scorer_and_counts_passes():
    goal = next(e for e in EVENTS if e["typeId"] == 16)
    text = render_events(minute_events(goal["periodId"], goal["timeMin"]), INFO)
    assert text.splitlines()[0] == f"{MatchClock(goal['periodId'], goal['timeMin']).label} (first half)"
    assert f"RIV {INFO.player(goal['playerId'])}: GOAL" in text
    assert "passes: " in text and "completed" in text


def test_every_event_type_in_the_match_is_described_or_counted():
    counted = {1}           # passes are counted per team
    paired = {(4, 1)}       # the fouled side of a foul; the foul itself is described
    periods = {30, 32}      # rendered once per period
    for e in EVENTS:
        if e["typeId"] in counted | periods or ((e["typeId"], e["outcome"]) in paired and not describe(e)):
            continue
        assert describe(e), e


def test_half_time_and_empty_minutes_render():
    assert "first half ends" in render_events(minute_events(1, 46) + minute_events(1, 47), INFO)
    assert render_events([], INFO) == "No recorded events."


def test_stats_table():
    row = {"periodId": 2, "minuteLabel": "71'", "goals": 0, "possessionPct": 52.5, "shots": 6, "shotsOnTarget": 2,
           "passes": 300, "passesCompleted": 260, "corners": 3, "fouls": 8, "yellowCards": 2, "redCards": 1}
    text = render_stats([{**row, "position": "home"}, {**row, "position": "away", "goals": 1}], INFO)
    assert "Score: Riverside FC (home) 0 - 1 Harbour Athletic (away)" in text
    assert "| Shots (on target) | 6 (2) | 6 (2) |" in text
    assert render_stats([], INFO) == "No statistics yet."


def test_ledger_explains_who_benefits_and_marks_overturns():
    rows = [
        {"id": 1, "keyType": "Goal", "detail": None, "contestantId": "c-har", "playerId": "p-har-09",
         "periodId": 2, "timeMin": 52, "timeSec": 24},
        {"id": 2, "keyType": "VarOverturn", "detail": "goal-overturned", "contestantId": "c-har",
         "playerId": "p-har-09", "periodId": 2, "timeMin": 53, "timeSec": 34},
        {"id": 3, "keyType": "PenaltyAwarded", "detail": "conceded", "contestantId": "c-har", "playerId": "p-har-05",
         "periodId": 1, "timeMin": 37, "timeSec": 41},
        {"id": 4, "keyType": "OwnGoal", "detail": None, "contestantId": "c-riv", "playerId": "p-riv-05",
         "periodId": 2, "timeMin": 84, "timeSec": 36},
    ]
    lines = render_ledger(rows, INFO, overturned={1}).splitlines()
    assert lines[0] == "- 38' 37:41: Penalty to Riverside FC, conceded by Bauer (Harbour Athletic)"
    assert lines[1].endswith("Goal for Harbour Athletic, Adeyemi [later overturned by VAR]")
    assert "VAR overturns the Harbour Athletic goal (Adeyemi)" in lines[2]
    assert "Own goal by Byrne (Riverside FC), counts for Harbour Athletic" in lines[3]
